rocci_defaults.source:
@component Hello = |{ name ?? "World" }|
    <p>Hello, {name}</p>

@component Greeting = |{}|
    <Hello />

@test helloDefault = hello({}) == "<p>Hello, World</p>"
@test greetingDefault = greeting({}) == "<p>Hello, World</p>"

sources.EmptyDefault.roc:
EmptyDefault := [].{
    Config := { value : I64 ?? 42 }
    get : Config -> I64
    get = |{ value }| value
}
expect EmptyDefault.get({}) == 42

sources.Indexed.roc:
Indexed := [].{
    values = [10.I64, 20, 30].iter().with_index()
    indexed = Iter.fold(values, [], |acc, item| acc.append(item))
}
expect Indexed.indexed == [(0, 10), (1, 20), (2, 30)]

sources.RecursiveUnion.roc:
RecursiveUnion := [].{
    walk : List(U8) -> Try({}, [BadUtf8, InvalidPercentEncoding])
    walk = |bytes|
        match bytes {
            [] => Ok({})
            [0, ..] => Err(BadUtf8)
            [1, ..] => Err(InvalidPercentEncoding)
            [_, .. as tail] => walk(tail)
        }
}
expect RecursiveUnion.walk([2, 3, 4]) == Ok({})
expect RecursiveUnion.walk([2, 0]) == Err(BadUtf8)
expect RecursiveUnion.walk([2, 1]) == Err(InvalidPercentEncoding)

sources.StructuralDefaults.roc:
StructuralDefaults := [].{
    get : { value : I64 ?? 42 } -> I64
    get = |{ value }| value
}
expect StructuralDefaults.get({}) == 42

sources.BoolDefaults.roc:
BoolDefaults := [].{
    Config := { value : Bool ?? True }
    get : Config -> Bool
    get = |{ value }| value
    direct = get({}) == True
    nominal = get(Config.{}) == True
}
expect BoolDefaults.direct
expect BoolDefaults.nominal

sources.BoolLowercase.roc:
BoolLowercase := [].{
    Config := { value : Bool ?? Bool.true }
    get : Config -> Bool
    get = |{ value }| value
}
expect BoolLowercase.get(BoolLowercase.Config.{}) == True
